export type Person = (typeof CORPUS_PEOPLE)[number];

export interface PlantedMessage {
  key: string;
  room: RoomKey;
  sender: Person;
  body: string;
}

export type QuestionCategory = 'identifier' | 'paraphrase' | 'lexical';

export interface EvalQuestion {
  id: string;
  room: RoomKey;
  category: QuestionCategory;
  question: string;
  /** Keys into PLANTED. Order is irrelevant; all of them count as relevant. */
  relevant: string[];
}

